//! `docs:cli`: Markdown reference generated from the clap definitions.

use std::fmt::Write;

use clap::Command;

pub fn markdown(cli: &Command, runtime: &Command, auth: &Command, admin: &Command) -> String {
    let mut out = String::from(
        "# CLI reference\n\n<!-- Generated by `rustcms docs:cli`; do not edit. -->\n\n\
         `rustcms` creates applications and generates code. Other commands run inside the\n\
         application in the current directory (`cargo run -- <command>`), or with its binary\n\
         (`./blog <command>`); `cargo run -- --help` lists them all, the application's own included.\n\n\
         ## Global commands\n\n",
    );
    section(&mut out, cli, &["help"]);
    out.push_str("## Application commands\n\n");
    section(&mut out, runtime, &["help"]);
    out.push_str("## Auth commands\n\nAdded by `AuthProvider` (registered in new applications).\n\n");
    section(&mut out, auth, &[]);
    out.push_str("## Admin panel commands\n\nAdded by `AdminProvider` (`media:prune` with `media()`).\n\n");
    section(&mut out, admin, &[]);
    out
}

fn section(out: &mut String, command: &Command, skip: &[&str]) {
    for sub in command.get_subcommands().filter(|s| !skip.contains(&s.get_name())) {
        let _ = writeln!(out, "### `{}`\n", sub.get_name());
        if let Some(about) = sub.get_about() {
            let _ = writeln!(out, "{about}\n");
        }
        // Hidden arguments are for contributors (e.g. `new --rustcms-path`).
        let args: Vec<_> = sub
            .get_arguments()
            .filter(|a| !a.is_hide_set() && !matches!(a.get_id().as_str(), "help" | "version"))
            .collect();
        if args.is_empty() {
            continue;
        }
        out.push_str("| Argument | Description |\n|---|---|\n");
        for arg in args {
            let name = match (arg.get_short(), arg.get_long()) {
                (Some(s), Some(l)) => format!("`-{s}, --{l}`"),
                (None, Some(l)) => format!("`--{l}`"),
                _ => format!("`<{}>`", arg.get_id()),
            };
            let help = arg.get_help().map(ToString::to_string).unwrap_or_default();
            let default = arg
                .get_default_values()
                .first()
                .and_then(|v| v.to_str())
                .map(|d| format!(" (default: `{d}`)"))
                .unwrap_or_default();
            let _ = writeln!(out, "| {name} | {help}{default} |");
        }
        out.push('\n');
    }
}
